// Smoothly frame an entity or group with 15% margin padding:
await camera.frameAnimated(myDiagram, 1000, {
    padding: 0.15,
    direction: [0, 0, 1], // View from front (+Z)
    updateFocusDist: true // Place DoF focal plane at diagram center
});

export class RenderView {
    public camera: Camera;
    public viewport: [number, number, number, number]; // [x, y, w, h] normalized
    public clearColor: boolean;
    public clearDepth: boolean;
    public renderTarget: RenderTarget | null;
    public layerMask: number;
}
